        function getTrialActionButtons(student) {
            const id = student.id;
            let btns = [`<button class="action-btn view" onclick="viewStudent('${id}')" title="Xem">👁️</button>`];

            if (student.status === 'Học Thử') {
                if (canCreate('appointments')) {
                    btns.push(`<button class="action-btn schedule" onclick="openAppointmentModalForStudent('${id}')" title="Đặt lịch">📅</button>`);
                }
                if (canEdit('trial')) {
                    btns.push(`<button class="action-btn edit" onclick="confirmTrialCompleted('${id}')" title="Xác nhận HT">✅</button>`);
                }
            } else if (student.status === 'Chờ Đăng Ký') {
                if (canCreate('registrations')) {
                    btns.push(`<button class="action-btn receipt" onclick="openRegistrationModalForStudent('${id}')" title="Tạo Phiếu ĐK">📋</button>`);
                }
            }
            return btns.join('');
        }

