        function saveReceipt(event) {
            event.preventDefault();

            const studentId = document.getElementById('receiptStudentId').value;
            const student = students.find(s => s.id === studentId);
            const editId = document.getElementById('editReceiptId').value;

            const data = {
                studentId,
                type: document.getElementById('receiptType').value,
                parentName: student?.parentName || '',
                parentPhone: student?.parentPhone || '',
                registrationId: document.getElementById('receiptRegistrationSelect')?.value || null,
                description: document.getElementById('receiptDescription').value.trim(),
                amount: parseCurrencyInput(document.getElementById('receiptAmount').value),
                date: document.getElementById('receiptDate').value,
                notes: document.getElementById('receiptNotes').value.trim()
            };

            // Validation
            if (!studentId) {
                showNotification('Vui lòng chọn học viên!', 'error');
                return;
            }

            if (!data.type) {
                showNotification('Vui lòng chọn loại biên lai!', 'error');
                return;
            }

            if (data.amount <= 0) {
                showNotification('Số tiền phải lớn hơn 0!', 'error');
                return;
            }

            if (editId) {
                // CẬP NHẬT - Giữ nguyên receiptCode cũ
                const index = receipts.findIndex(r => r.id === editId);
                if (index !== -1) {
                    receipts[index] = {
                        ...receipts[index],
                        ...data,
                        // QUAN TRỌNG: Giữ nguyên receiptCode cũ
                        receiptCode: receipts[index].receiptCode,
                        updatedAt: new Date().toISOString()
                    };
                    showNotification('Cập nhật biên lai thành công!', 'success');
                }
            } else {
                // THÊM MỚI - Tạo receiptCode mới
                const newReceipt = {
                    id: generateId(),
                    receiptCode: typeof generateReceiptCode === 'function' ? generateReceiptCode() : ('BL-' + Date.now().toString().slice(-8)),
                    ...data,
                    createdBy: currentUser?.id || null,
                    createdAt: new Date().toISOString()
                };
                receipts.push(newReceipt);
                showNotification('Tạo biên lai thành công!', 'success');
            }

            saveData('receipts', receipts);
            closeModal('receiptModal');

            // Reset form title
            const modalTitle = document.querySelector('#receiptModal .modal-header h2');
            if (modalTitle) modalTitle.textContent = '🧾 Tạo Biên Lai';

            renderAll();
        }



        function searchReceipts() { paginationState.receipts.page = 1; renderReceiptsTable(); }

        function getFilteredReceipts() {
            const searchTerm = document.getElementById('searchReceipt')?.value?.toLowerCase() || '';
            let filtered = [...receipts];
            if (searchTerm) {
                filtered = filtered.filter(r => {
                    const student = students.find(s => s.id === r.studentId);
                    return r.description.toLowerCase().includes(searchTerm) || student?.name.toLowerCase().includes(searchTerm);
                });
            }
            return filtered.sort((a, b) => new Date(b.date) - new Date(a.date));
        }

        function renderReceiptsTable() {
            const filtered = getFilteredReceipts();
            const { data, total, totalPages, currentPage } = getPaginatedData(filtered, 'receipts');
            const tbody = document.getElementById('receiptsTableBody');

            if (data.length === 0) {
                tbody.innerHTML = `<tr><td colspan="7"><div class="empty-state"><div class="empty-state-icon">🧾</div><p>Không có biên lai</p></div></td></tr>`;
                renderPagination('receiptsPagination', 'receipts', 0, 0, 1);
                return;
            }

            tbody.innerHTML = data.map((r, idx) => {
                const student = students.find(s => s.id === r.studentId);
                return `
            <tr>
                <td><strong class="text-primary">${r.receiptCode || '#' + String(total - idx).padStart(4, '0')}</strong></td>
                <td><span class="subject-tag">${r.type}</span></td>
                <td>${student?.name || 'N/A'}</td>
                <td>${r.description}</td>
                <td><strong class="text-success">${formatCurrency(r.amount)}</strong></td>
                <td>${formatDate(r.date)}</td>
                <td><div class="action-buttons">
                    <button class="action-btn view" onclick="viewReceipt('${r.id}')" title="Xem">👁️</button>
                    ${canDelete('receipts') ? `<button class="action-btn delete" onclick="deleteReceipt('${r.id}')" title="Xóa">🗑️</button>` : ''}
                </div></td>
            </tr>
        `;
            }).join('');

            renderPagination('receiptsPagination', 'receipts', total, totalPages, currentPage);
        }

        function viewReceipt(id) {
            const receipt = receipts.find(r => r.id === id);
            if (!receipt) return;
            const student = students.find(s => s.id === receipt.studentId);
            const reg = receipt.registrationId ? registrations.find(r => r.id === receipt.registrationId) : null;
            if (typeof generateReceiptHTML === 'function') {
                document.getElementById('receiptPreviewContent').innerHTML = generateReceiptHTML(receipt, student, reg);
            } else {
                document.getElementById('receiptPreviewContent').innerHTML = `
                    <div style="padding:20px;">
                        <h3 style="text-align:center;color:#1e40af;">BIÊN LAI THU TIỀN</h3>
                        <p style="text-align:center;color:#475569;">Mã: ${receipt.receiptCode || ''}</p>
                        <hr>
                        <p><strong>Học viên:</strong> ${student ? student.name : 'N/A'}</p>
                        <p><strong>Phụ huynh:</strong> ${receipt.parentName || ''} - ${receipt.parentPhone || ''}</p>
                        <p><strong>Loại:</strong> ${receipt.type}</p>
                        <p><strong>Nội dung:</strong> ${receipt.description}</p>
                        <p style="font-size:18px;color:#27AE60;"><strong>Số tiền: ${formatCurrency(receipt.amount)}</strong></p>
                        <p><strong>Ngày:</strong> ${formatDate(receipt.date)}</p>
                        ${receipt.notes ? `<p><strong>Ghi chú:</strong> ${receipt.notes}</p>` : ''}
                    </div>`;
            }
            openModal('viewReceiptModal');
        }

