        function exportAllToExcel() {
            try {
                if (typeof XLSX === 'undefined') {
                    throw new Error('Thư viện XLSX chưa được tải!');
                }

                const wb = XLSX.utils.book_new();

                // Sheet Học viên
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(students.map(s => ({
                    'Tên': s.name,
                    'Tuổi': s.age,
                    'Phụ huynh': s.parentName,
                    'SĐT': s.parentPhone,
                    'Email': s.parentEmail || '',
                    'Môn học': s.subjects.join(', '),
                    'Trạng thái': s.status,
                    'Ngày tạo': s.createdAt ? formatDate(s.createdAt.split('T')[0]) : ''
                }))), 'Học Viên');

                // Sheet Phiếu ĐK
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(registrations.map(r => ({
                    'Mã phiếu': r.regCode,
                    'Học viên': r.studentName,
                    'Môn': r.subject,
                    'Số buổi': r.totalSessions || '-',
                    'Học phí': r.tuitionFee,
                    'Giảm': r.discountAmount,
                    'Thành tiền': r.finalAmount,
                    'Ngày ĐK': formatDate(r.registrationDate)
                }))), 'Phiếu ĐK');

                // Sheet Biên lai
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(receipts.map(r => ({
                    'Mã BL': r.receiptCode || '',
                    'Loại': r.type,
                    'Học viên': students.find(s => s.id === r.studentId)?.name || '',
                    'Nội dung': r.description,
                    'Số tiền': r.amount,
                    'Ngày': formatDate(r.date)
                }))), 'Biên Lai');

                // Sheet Giáo viên
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(teachers.map(t => ({
                    'Họ tên': t.fullName,
                    'SĐT': t.phone,
                    'Email': t.email || '',
                    'Môn dạy': t.subjects.join(', '),
                    'Loại lương': t.salaryType,
                    'Trạng thái': t.status === 'active' ? 'Đang dạy' : 'Nghỉ'
                }))), 'Giáo Viên');

                // Sheet Lớp học
                XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(classes.map(c => {
                    const subject = subjects.find(s => s.id === c.subjectId);
                    const teacher = teachers.find(t => t.id === c.teacherId);
                    return {
                        'Tên lớp': c.className,
                        'Môn học': subject ? subject.name : '',
                        'Giáo viên': teacher ? teacher.fullName : '',
                        'Loại': c.classType === 'group' ? 'Nhóm' : '1-1',
                        'Sĩ số tối đa': c.maxStudents,
                        'Trạng thái': c.status
                    };
                })), 'Lớp Học');

                XLSX.writeFile(wb, `BaoCao_${formatDateFile()}.xlsx`);
                showNotification('✅ Xuất Excel thành công!', 'success');

            } catch (error) {
                console.error('Lỗi export Excel:', error);
                showNotification('❌ Lỗi xuất Excel: ' + error.message, 'error');
            }
        }

