        function generateBankQR() {
            const container = document.getElementById('bankQRCode');
            if (!bankInfo.accountNumber || !bankInfo.bankName) {
                container.innerHTML = '<p class="text-muted">Nhập thông tin ngân hàng để tạo QR</p>';
                return;
            }

            // Tạo nội dung QR (VietQR format đơn giản)
            const qrContent = `${bankInfo.bankName}|${bankInfo.accountNumber}|${bankInfo.accountName || ''}`;

            container.innerHTML = '';
            try {
                new QRCode(container, {
                    text: qrContent,
                    width: 150,
                    height: 150,
                    colorDark: '#2C3E50',
                    colorLight: '#ffffff'
                });
            } catch (e) {
                container.innerHTML = '<p class="text-muted">Không thể tạo QR</p>';
            }
        }

