        // ===== 30.8 Export báo cáo =====
        function exportReportToExcel() {
            const { fromDate, toDate } = reportData;
            const wb = XLSX.utils.book_new();

            // Sheet 1: Doanh thu
            const revenueData = receipts
                .filter(r => r.date >= fromDate && r.date <= toDate)
                .map(r => {
                    const student = students.find(s => s.id === r.studentId);
                    return {
                        'Ngày': formatDate(r.date),
                        'Học viên': student ? student.name : '',
                        'Loại': r.type,
                        'Nội dung': r.description,
                        'Số tiền': r.amount
                    };
                });
            XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(revenueData), 'Doanh thu');

            // Sheet 2: Học viên
            const studentData = students.map(s => ({
                'Tên': s.name,
                'Tuổi': s.age,
                'Phụ huynh': s.parentName,
                'SĐT': s.parentPhone,
                'Trạng thái': s.status,
                'Ngày tạo': s.createdAt ? formatDate(s.createdAt.split('T')[0]) : ''
            }));
            XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(studentData), 'Học viên');

            // Sheet 3: Điểm danh
            const attendanceData = attendances
                .filter(a => a.attendanceDate >= fromDate && a.attendanceDate <= toDate)
                .map(a => {
                    const student = students.find(s => s.id === a.studentId);
                    const cls = classes.find(c => c.id === a.classId);
                    return {
                        'Ngày': formatDate(a.attendanceDate),
                        'Lớp': cls ? cls.className : '',
                        'Học viên': student ? student.name : '',
                        'Trạng thái': a.status === 'present' ? 'Có mặt' : a.status === 'late' ? 'Muộn' : a.status === 'absent' ? 'Vắng' : 'Có phép',
                        'Học bù': a.isMakeupSession ? 'Có' : ''
                    };
                });
            XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(attendanceData), 'Điểm danh');

            // Sheet 4: Công nợ
            const debtData = registrations.map(reg => {
                const student = students.find(s => s.id === reg.studentId);
                const debt = calculateDebtForRegistration(reg.id);
                return {
                    'Học viên': student ? student.name : '',
                    'Mã phiếu': reg.regCode,
                    'Môn học': reg.subject,
                    'Tổng tiền': debt.totalAmount,
                    'Đã đóng': debt.paidAmount,
                    'Còn nợ': debt.debtAmount
                };
            });
            XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(debtData), 'Công nợ');

            XLSX.writeFile(wb, `BaoCao_${fromDate}_${toDate}.xlsx`);
            showNotification('Xuất báo cáo Excel thành công!', 'success');
        }


